#include <bits/stdc++.h>
using namespace std;
// CRTP: the base is a template that knows the derived type.
template <class D>
struct Shape {
    double area() const { return static_cast<const D&>(*this).areaImpl(); } // no vtable
    void describe() const { cout << D::name << " area=" << area() << "\n"; }
};
struct Square : Shape<Square> {
    static constexpr const char* name = "Square";
    double s;
    explicit Square(double s) : s(s) {}
    double areaImpl() const { return s * s; }
};
struct Circle : Shape<Circle> {
    static constexpr const char* name = "Circle";
    double r;
    explicit Circle(double r) : r(r) {}
    double areaImpl() const { return 3.0 * r * r; } // pi ~ 3 to keep output exact
};
// Template function: the call is resolved at compile time and can inline.
template <class D> void show(const Shape<D>& s) { s.describe(); }
int main() {
    Square sq(4);
    Circle c(2);
    show(sq);
    show(c);
    // No vptr: the objects are just their data.
    cout << "sizeof(Square)=" << sizeof(Square) << " sizeof(double)=" << sizeof(double) << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// ---- "header": only a forward declaration of Impl is visible ----
class Counter {
public:
    Counter();
    ~Counter();                       // must be defined where Impl is complete
    Counter(Counter&&) noexcept;
    Counter& operator=(Counter&&) noexcept;
    void add(int x);
    int total() const;
private:
    struct Impl;
    unique_ptr<Impl> p_;              // the only data member clients see
};
// ---- "source file": the real data lives here ----
struct Counter::Impl {
    int sum = 0;
    vector<int> history;
};
Counter::Counter() : p_(make_unique<Impl>()) {}
Counter::~Counter() = default;        // Impl is complete here, so unique_ptr can delete it
Counter::Counter(Counter&&) noexcept = default;
Counter& Counter::operator=(Counter&&) noexcept = default;
void Counter::add(int x) { p_->sum += x; p_->history.push_back(x); }
int Counter::total() const { return p_->sum; }

int main() {
    Counter c;
    c.add(5);
    c.add(7);
    cout << "total=" << c.total() << "\n";
    // The class is one pointer wide, however much data Impl holds.
    cout << "sizeof(Counter)=" << sizeof(Counter) << " sizeof(void*)=" << sizeof(void*) << "\n";
    Counter d = std::move(c);
    cout << "moved total=" << d.total() << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// Minimal type-erased function<int(int)>.
class Fn {
    struct Concept {                         // abstract interface
        virtual ~Concept() = default;
        virtual int call(int) const = 0;
        virtual unique_ptr<Concept> clone() const = 0;
    };
    template <class F>
    struct Model : Concept {                 // remembers the real callable type F
        F f;
        explicit Model(F f) : f(std::move(f)) {}
        int call(int x) const override { return f(x); }
        unique_ptr<Concept> clone() const override { return make_unique<Model>(f); }
    };
    unique_ptr<Concept> p_;
public:
    template <class F> Fn(F f) : p_(make_unique<Model<F>>(std::move(f))) {}
    Fn(const Fn& o) : p_(o.p_->clone()) {}   // only the Model knows how to copy F
    int operator()(int x) const { return p_->call(x); }
};
int triple(int x) { return 3 * x; }
int main() {
    int offset = 10;
    Fn a = [offset](int x) { return x + offset; };  // lambda with state
    Fn b = triple;                                   // plain function
    Fn c = a;                                        // copy via clone()
    vector<Fn> all{a, b, c};
    for (auto& f : all) cout << f(4) << " ";         // same type, different callables
    cout << "\n";
}

#include <bits/stdc++.h>
using namespace std;
class Buffer {
    size_t n_;
    int* data_;
public:
    explicit Buffer(size_t n) : n_(n), data_(new int[n]()) {}
    Buffer(const Buffer& o) : n_(o.n_), data_(new int[o.n_]) { copy(o.data_, o.data_ + n_, data_); }
    ~Buffer() { delete[] data_; }
    friend void swap(Buffer& a, Buffer& b) noexcept {   // cannot throw
        swap(a.n_, b.n_);
        swap(a.data_, b.data_);
    }
    // Copy-and-swap: the by-value parameter does the risky allocation first.
    Buffer& operator=(Buffer other) noexcept {
        swap(*this, other);          // old buffer is freed when 'other' dies
        return *this;
    }
    int& operator[](size_t i) { return data_[i]; }
    size_t size() const { return n_; }
};
int main() {
    Buffer a(3), b(5);
    for (size_t i = 0; i < a.size(); i++) a[i] = int(i) + 1;
    b = a;                       // copy assign
    a[0] = 99;                   // b must be independent
    b = b;                       // self-assignment is safe
    cout << "a[0]=" << a[0] << " b[0]=" << b[0] << " b.size=" << b.size() << "\n";
    Buffer c(2);
    c = Buffer(4);               // rvalue: the parameter is move/elided
    cout << "c.size=" << c.size() << "\n";
}

#include <bits/stdc++.h>
using namespace std;
struct Bomb {
    int v;
    static inline int copies = 0;
    static inline bool armed = false;
    explicit Bomb(int v) : v(v) {}
    Bomb(const Bomb& o) : v(o.v) { if (armed && ++copies == 3) throw runtime_error("copy failed"); }
};
// Strong guarantee: copy into a temporary first, commit with a nothrow swap.
bool strongAssign(vector<Bomb>& dst, const vector<Bomb>& src) {
    try {
        vector<Bomb> tmp(src);       // may throw; dst untouched so far
        dst.swap(tmp);               // nothrow commit
        return true;
    } catch (exception&) { return false; }
}
// Only basic guarantee: dst is modified step by step.
bool basicAssign(vector<Bomb>& dst, const vector<Bomb>& src) {
    try {
        dst.clear();
        for (auto& b : src) dst.push_back(b);   // may throw half way
        return true;
    } catch (exception&) { return false; }
}
void show(const char* tag, const vector<Bomb>& v) {
    cout << tag << " size=" << v.size() << " [";
    for (auto& b : v) cout << b.v << " ";
    cout << "]\n";
}
int main() {
    vector<Bomb> src{Bomb(1), Bomb(2), Bomb(3), Bomb(4)};
    vector<Bomb> d1{Bomb(9)};
    Bomb::armed = true; Bomb::copies = 0;   // 3rd copy from now on throws
    cout << "strong ok=" << strongAssign(d1, src) << "\n";
    show("d1 after strong", d1);         // unchanged: [9]
    Bomb::armed = false;
    vector<Bomb> d2{Bomb(9)};
    Bomb::armed = true; Bomb::copies = 0;
    cout << "basic ok=" << basicAssign(d2, src) << "\n";
    show("d2 after basic ", d2);         // valid but changed: [1]
}

#include <bits/stdc++.h>
using namespace std;
template <class F>
class ScopeFail {
    F f_;
    int uncaught_ = std::uncaught_exceptions();   // exceptions in flight at creation
public:
    explicit ScopeFail(F f) : f_(std::move(f)) {}
    ScopeFail(const ScopeFail&) = delete;
    ~ScopeFail() { if (std::uncaught_exceptions() > uncaught_) f_(); } // more now => unwinding
};
template <class F>
class ScopeExit {
    F f_; bool active_ = true;
public:
    explicit ScopeExit(F f) : f_(std::move(f)) {}
    ScopeExit(ScopeExit&& o) noexcept : f_(std::move(o.f_)), active_(o.active_) { o.active_ = false; }
    void dismiss() { active_ = false; }
    ~ScopeExit() { if (active_) f_(); }
};
void work(bool fail) {
    ScopeExit cleanup([] { cout << "  cleanup always runs\n"; });
    ScopeFail rollback([] { cout << "  rollback (only on exception)\n"; });
    if (fail) throw runtime_error("boom");
    cout << "  work finished normally\n";
}
int main() {
    cout << "normal run:\n";
    work(false);
    cout << "failing run:\n";
    try { work(true); } catch (exception& e) { cout << "  caught " << e.what() << "\n"; }
}

#include <bits/stdc++.h>
using namespace std;
class File {
    bool open_ = true;
    string name_;
public:
    explicit File(string n) : name_(std::move(n)) {}
    // Explicit close reports errors to the caller.
    void close(bool simulateFailure) {
        if (!open_) return;
        open_ = false;
        if (simulateFailure) throw runtime_error("flush failed for " + name_);
        cout << "closed " << name_ << "\n";
    }
    // Destructors are implicitly noexcept: never let an exception escape.
    ~File() {
        if (open_) {
            try { close(false); } catch (...) { cerr << "swallowed error\n"; }
        }
    }
};
int main() {
    cout << "noexcept(~File)=" << boolalpha << is_nothrow_destructible_v<File> << "\n";
    try {
        File f("a.txt");
        f.close(true);                 // caller can handle the failure
    } catch (exception& e) {
        cout << "caller handled: " << e.what() << "\n";
    }
    { File g("b.txt"); }               // destructor does best-effort close
    cout << "done\n";
}

#include <bits/stdc++.h>
#include <coroutine>
using namespace std;
struct Gen {
    struct promise_type {                      // customizes the coroutine
        int current = 0;
        Gen get_return_object() { return Gen{coroutine_handle<promise_type>::from_promise(*this)}; }
        suspend_always initial_suspend() noexcept { return {}; }   // lazy start
        suspend_always final_suspend() noexcept { return {}; }     // keep frame for done()
        suspend_always yield_value(int v) noexcept { current = v; return {}; }
        void return_void() {}
        void unhandled_exception() { terminate(); }
    };
    coroutine_handle<promise_type> h;          // non-owning pointer to the frame
    explicit Gen(coroutine_handle<promise_type> h) : h(h) {}
    Gen(Gen&& o) noexcept : h(exchange(o.h, nullptr)) {}
    ~Gen() { if (h) h.destroy(); }             // we own the frame
    bool next() { h.resume(); return !h.done(); }
    int value() const { return h.promise().current; }
};
Gen fib(int n) {
    long a = 0, b = 1;
    for (int i = 0; i < n; i++) { co_yield int(a); long t = a + b; a = b; b = t; }
}
int main() {
    Gen g = fib(8);
    cout << "fib:";
    while (g.next()) cout << " " << g.value();   // resumes, runs to next co_yield
    cout << "\n";
}

#include <bits/stdc++.h>
#include <coroutine>
using namespace std;
struct Task {
    struct promise_type {
        Task get_return_object() { return Task{coroutine_handle<promise_type>::from_promise(*this)}; }
        suspend_always initial_suspend() noexcept { return {}; }
        suspend_always final_suspend() noexcept { return {}; }
        void return_void() {}
        void unhandled_exception() { terminate(); }
    };
    coroutine_handle<promise_type> h;
    explicit Task(coroutine_handle<promise_type> h) : h(h) {}
    Task(Task&& o) noexcept : h(exchange(o.h, nullptr)) {}
    ~Task() { if (h) h.destroy(); }
};
long total = 0;
// Stackless: each coroutine keeps only its own locals (id, step) in a small heap frame.
Task worker(int id) {
    for (int step = 1; step <= 3; step++) {
        total += id * step;
        co_await suspend_always{};        // suspend; the stack is not kept
    }
}
int main() {
    const int N = 10000;                  // ten thousand live coroutines
    vector<Task> tasks;
    for (int i = 1; i <= N; i++) tasks.push_back(worker(i));
    for (int round = 0; round < 4; round++)       // round-robin scheduler
        for (auto& t : tasks) if (!t.h.done()) t.h.resume();
    long expect = 6L * N * (N + 1) / 2;   // sum of id*(1+2+3)
    cout << "coroutines=" << N << " total=" << total << " expected=" << expect << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// Same public API, two library versions: the ABI differs.
namespace v1 { struct Point { int x; int y; }; }
namespace v2 { struct Point { int id; int x; int y; }; }   // added a field in front
int main() {
    cout << "v1: sizeof=" << sizeof(v1::Point)
         << " offset(y)=" << offsetof(v1::Point, y) << "\n";
    cout << "v2: sizeof=" << sizeof(v2::Point)
         << " offset(y)=" << offsetof(v2::Point, y) << "\n";
    // An old program compiled against v1 reads y at offset 4.
    v2::Point p{100, 7, 8};
    const char* raw = reinterpret_cast<const char*>(&p);
    int oldY;
    memcpy(&oldY, raw + offsetof(v1::Point, y), sizeof(int));
    cout << "true y=" << p.y << " but old binary reads y=" << oldY << "\n";
}

#include <bits/stdc++.h>
#include <cxxabi.h>
using namespace std;
int add(int a, int b) { return a + b; }
double add(double a, double b) { return a + b; }   // overload: needs a different symbol
namespace ns { struct Widget { void click() {} }; }
extern "C" int add_c(int a, int b) { return a + b; } // plain symbol "add_c", no mangling
// Demangle a mangled name using the Itanium ABI helper.
string demangle(const char* m) {
    int st = 0;
    char* d = abi::__cxa_demangle(m, nullptr, nullptr, &st);
    string s = st == 0 ? d : m;
    free(d);
    return s;
}
int main() {
    // typeid names on GCC/Clang are mangled type names.
    cout << "raw   : " << typeid(ns::Widget).name() << "\n";
    cout << "pretty: " << demangle(typeid(ns::Widget).name()) << "\n";
    cout << "raw   : " << typeid(int (*)(int, int)).name() << "\n";
    cout << "pretty: " << demangle(typeid(int (*)(int, int)).name()) << "\n";
    cout << add(1, 2) << " " << add(1.5, 2.5) << " " << add_c(3, 4) << "\n";
}

#include <bits/stdc++.h>
using namespace std;
// A safe library boundary: only C types, opaque handle, creator also destroys.
extern "C" {
struct Lib;                                       // opaque to callers
Lib* lib_create(const char* name);
int lib_greeting(const Lib* l, char* buf, size_t cap);   // caller-provided buffer
void lib_destroy(Lib* l);                         // freed by the side that allocated
}
// ---- implementation side (would live in the DLL) ----
struct Lib { string name; };
Lib* lib_create(const char* name) { return new Lib{name}; }
int lib_greeting(const Lib* l, char* buf, size_t cap) {
    string s = "hello, " + l->name;
    if (s.size() + 1 > cap) return -1;            // report "too small" with an error code
    memcpy(buf, s.c_str(), s.size() + 1);
    return int(s.size());
}
void lib_destroy(Lib* l) { delete l; }
// ---- client side ----
int main() {
    Lib* l = lib_create("world");
    char small[4], big[32];
    cout << "small buffer -> " << lib_greeting(l, small, sizeof small) << "\n";
    int n = lib_greeting(l, big, sizeof big);
    cout << "big buffer   -> " << n << " \"" << big << "\"\n";
    lib_destroy(l);                               // never call delete on it yourself
}

