struct PlainBase { ~PlainBase() { cout << "  ~PlainBase\n"; } };           // NOT virtual
struct PlainDerived : PlainBase { ~PlainDerived() { cout << "  ~PlainDerived\n"; } };
struct VBase { virtual ~VBase() { cout << "  ~VBase\n"; } };               // virtual
struct VDerived : VBase { ~VDerived() { cout << "  ~VDerived\n"; } };
int main() {
    cout << "shared_ptr<PlainBase> from make_shared<PlainDerived> (deleter remembers Derived):\n";
    { shared_ptr<PlainBase> p = make_shared<PlainDerived>(); }
    cout << "unique_ptr<VBase> holding VDerived (virtual destructor):\n";
    { unique_ptr<VBase> p = make_unique<VDerived>(); }
    // unique_ptr<PlainBase> p = make_unique<PlainDerived>(); would be undefined behavior.
    cout << "shared_ptr<void> still destroys correctly:\n";
    { shared_ptr<void> p = make_shared<PlainDerived>(); }
}

#include <bits/stdc++.h>
using namespace std;
struct T {
    int id;
    T(int i) : id(i) { cout << "  ctor " << id << "\n"; }
    T(const T& o) : id(o.id) { cout << "  copy " << id << "\n"; }
    T(T&& o) noexcept : id(o.id) { cout << "  move " << id << "\n"; }
    ~T() { cout << "  dtor " << id << "\n"; }
};
struct Pinned {                         // no copy, no move at all
    Pinned() { cout << "  Pinned ctor\n"; }
    Pinned(const Pinned&) = delete;
};
Pinned makePinned() { return Pinned(); }                // C++17: guaranteed elision
T single() { T x(1); return x; }                        // NRVO usually applies
T twoCandidates(bool b) { T x(2), y(3); if (b) return x; return y; } // implicit move
T withMove() { T x(4); return std::move(x); }           // bad: disables NRVO
int main() {
    cout << "pinned:\n"; Pinned p = makePinned();
    cout << "single:\n"; { T a = single(); }
    cout << "two candidates:\n"; { T a = twoCandidates(true); }
    cout << "return std::move:\n"; { T a = withMove(); }
}

#include <bits/stdc++.h>
using namespace std;
struct Base {
    virtual void f(int x = 1) { cout << "Base::f x=" << x << "\n"; }
    virtual ~Base() = default;
    Base() { cout << "Base ctor: "; who(); }
    virtual void who() { cout << "I am Base\n"; }
};
struct Derived : Base {
    void f(int x = 2) override { cout << "Derived::f x=" << x << "\n"; }
    void who() override { cout << "I am Derived\n"; }
};
void byValue(Base b) { b.who(); }
void print(int) { cout << "print(int)\n"; }
void print(long) { cout << "print(long)\n"; }
void print(double) { cout << "print(double)\n"; }
int main() {
    Derived d;                 // step 3: no deep dispatch in constructors
    Base* p = &d;
    p->f();                    // virtual function, but default argument is the STATIC type's
    byValue(d);                // slicing
    print('a');                // promotion to int beats conversion
    print(3.0f);               // float promotes to double
    int i = 7;
    cout << i / 2 << " " << -7 / 2 << " " << -7 % 3 << "\n"; // truncating division
}

#include <bits/stdc++.h>
using namespace std;
// Closed set with variant: value semantics, no heap, std::visit.
struct Circle { double r; };
struct Rect { double w, h; };
using ShapeV = variant<Circle, Rect>;
// Open set with virtual: pointer semantics.
struct Shape { virtual double area() const = 0; virtual ~Shape() = default; };
struct VCircle : Shape { double r; VCircle(double r) : r(r) {} double area() const override { return 3 * r * r; } };
struct VRect : Shape { double w, h; VRect(double w, double h) : w(w), h(h) {} double area() const override { return w * h; } };
int main() {
    vector<ShapeV> a{Circle{2}, Rect{3, 4}, Circle{1}};
    double sumV = 0;
    for (auto& s : a)
        sumV += visit([](auto& x) {
            if constexpr (is_same_v<decay_t<decltype(x)>, Circle>) return 3 * x.r * x.r;
            else return x.w * x.h;
        }, s);
    vector<unique_ptr<Shape>> b;
    b.push_back(make_unique<VCircle>(2));
    b.push_back(make_unique<VRect>(3, 4));
    b.push_back(make_unique<VCircle>(1));
    double sumP = 0;
    for (auto& s : b) sumP += s->area();
    cout << "variant total=" << sumV << " virtual total=" << sumP << "\n";
    cout << "sizeof(ShapeV)=" << sizeof(ShapeV) << " (stored inline, no heap)\n";
}
